using ClinicaPacientes.Application.Interfaces; using ClinicaPacientes.Domain.Entities; using ClinicaPacientes.Infrastructure.Data; using Microsoft.EntityFrameworkCore;
namespace ClinicaPacientes.Infrastructure.Repositories;
public class PacienteRepository(ClinicaDbContext db):IPacienteRepository { public async Task<IReadOnlyList<Paciente>> ObtenerTodosAsync(string? b,CancellationToken ct){var q=db.Pacientes.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(b))q=q.Where(p=>p.Nombres.Contains(b)||p.Apellidos.Contains(b)||p.Documento.Contains(b));return await q.OrderBy(p=>p.Apellidos).ThenBy(p=>p.Nombres).ToListAsync(ct);} public Task<Paciente?> ObtenerPorIdAsync(int id,CancellationToken ct)=>db.Pacientes.FirstOrDefaultAsync(p=>p.Id==id,ct); public Task<bool> ExisteDocumentoAsync(string doc,int? excl,CancellationToken ct)=>db.Pacientes.AnyAsync(p=>p.Documento==doc&&(!excl.HasValue||p.Id!=excl),ct);public Task AgregarAsync(Paciente p,CancellationToken ct)=>db.Pacientes.AddAsync(p,ct).AsTask();public Task GuardarCambiosAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);public Task EliminarAsync(Paciente p,CancellationToken ct){db.Pacientes.Remove(p);return Task.CompletedTask;}}
